public async Task<string> GenerateWithBudgetAsync(
    string prompt,
    int maxInputTokens,
    int maxOutputTokens,
    CancellationToken ct = default)
{
    var inputTokens = await _tokenizer.CountTokensAsync(prompt, ct);
    if (inputTokens > maxInputTokens)
        throw new InvalidOperationException($"Prompt exceeds token budget: {inputTokens}");

    var response = await _chatClient.GetResponseAsync(
        new[] { new ChatMessage(ChatRole.User, prompt) },
        new ChatOptions { MaxOutputTokens = maxOutputTokens },
        ct);

    return response.Messages.Last().Text ?? string.Empty;
}
